        List<Customer> page = customers.stream()
                .filter(matching(filter))
                .sorted(comparatorFor(sorts))
                .skip(offset)
                .limit(limit)
                .toList();
        queryLog.recordPage(offset, limit, page.size());
        return page;
    }

    /** Returns the number of customers matching {@code filter}. */
    public int count(CustomerFilter filter) {
        int total = (int) customers.stream().filter(matching(filter)).count();
        queryLog.recordCount(total);
        return total;
    }

    private static Predicate<Customer> matching(CustomerFilter filter) {
        List<String> nameTerms = Arrays.stream(filter.name().trim().split("\\s+"))
                .filter(term -> !term.isEmpty())
                .map(CustomerRepository::normalize)
                .toList();
        Set<CustomerStatus> statuses = filter.statuses();
        return customer -> {
            if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
                return false;
            }
            if (nameTerms.isEmpty()) {
                return true;
            }
            String first = normalize(customer.firstName());
            String last = normalize(customer.lastName());
            return nameTerms.stream().allMatch(term -> first.contains(term) || last.contains(term));
        };
    }

    private static String normalize(String s) {
        String decomposed = Normalizer.normalize(s, Normalizer.Form.NFD);
        return decomposed.replaceAll("\\p{M}", "").toLowerCase(Locale.ROOT);
