+/**
+ * Drives the real, running application through a headless Chromium browser
+ * (via Playwright / Drama Finder), to check what {@code CustomerListViewTest}
+ * cannot: the address bar contents and how many backend queries typing costs.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewBrowserIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @BeforeEach
+    void clearQueryLog() {
+        queryLog.clear();
+    }
+
+    private TextFieldElement nameFilter() {
+        return new TextFieldElement(getPage().locator("vaadin-text-field[placeholder='Filter by name']"));
+    }
+
+    private MultiSelectComboBoxElement statusFilter() {
+        return MultiSelectComboBoxElement.getByLabel(getPage(), "Status");
+    }
+
+    @Test
+    void typingNarrowsTheGridWithoutOneBackendQueryPerKeystroke() {
+        nameFilter().getInputLocator()
+                .pressSequentially("virtanen", new Locator.PressSequentiallyOptions().setDelay(30));
+        getPage().waitForTimeout(700);
+
+        GridElement grid = GridElement.get(getPage());
+        assertEquals(15, grid.getTotalRowCount());
+
+        assertTrue(queryLog.countQueries().size() <= 2,
+                "Typing a 9-letter name should cost one or two backend queries, not one per keystroke; got "
+                        + queryLog.countQueries().size() + ": " + queryLog.countQueries());
+    }
+
+    @Test
+    void changingTheFilterUpdatesTheAddressBar() {
+        nameFilter().setValue("vir");
+        getPage().waitForTimeout(700);
+        assertTrue(getPage().url().contains("name=vir"),
+                "Expected the address bar to contain name=vir, was: " + getPage().url());
+
+        statusFilter().selectItem("ACTIVE");
+        getPage().waitForTimeout(300);
+        assertTrue(getPage().url().contains("status=ACTIVE"),
+                "Expected the address bar to contain status=ACTIVE, was: " + getPage().url());
+
+        nameFilter().clear();
+        getPage().waitForTimeout(700);
+        assertTrue(!getPage().url().contains("name="),
+                "Clearing the name filter should drop it from the address bar, was: " + getPage().url());
+    }
+
+    @Test
+    void openingWithQueryParametersAppliesTheFilter() {
+        getPage().navigate(getUrl() + "/?name=vir&status=ACTIVE,CLOSED");
+        getPage().waitForTimeout(700);
+
+        assertEquals("vir", nameFilter().getValue());
+        GridElement grid = GridElement.get(getPage());
+        assertTrue(grid.getTotalRowCount() > 0 && grid.getTotalRowCount() < 15);
+    }
+}
